from __future__ import annotations
import csv,json,os,threading,time,webbrowser
from datetime import datetime
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse
ROOT=Path(os.environ.get('THE_JOCKEY_RESEARCH_ROOT',Path.home()/'Downloads'/'THE-JOCKEY-RESEARCH'));HOST='127.0.0.1';PORT=int(os.environ.get('THE_JOCKEY_DASHBOARD_PORT','8791'))
def rj(p,d=None):
 try:return json.loads(p.read_text(encoding='utf-8-sig'))
 except:return d
def rc(p):
 try:
  with p.open('r',encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
 except:return []
def tail(p,n=80):
 try:return p.read_text(encoding='utf-8',errors='replace').splitlines()[-n:]
 except:return []
def build():
 core=ROOT/'CORE';reports=core/'reports';data=core/'data';program=rj(core/'program.json',{}) or {};missions=program.get('missions',[]);current=next((m for m in missions if str(m.get('state','')).upper()=='READY'),next((m for m in missions if str(m.get('state','')).upper()=='PENDING'),None));complete=sum(str(m.get('state','')).upper()=='COMPLETE' for m in missions)
 sup=rj(ROOT/'checkpoints'/'autonomy_supervisor_state.json',{}) or {};temporal=rj(ROOT/'checkpoints'/'temporal_sample_optimizer_state.json',{}) or {};universal=rj(ROOT/'checkpoints'/'universal_model_director_state.json',{}) or {};domain=rj(ROOT/'checkpoints'/'domain_research_director_state.json',{}) or {};ensemble=rj(ROOT/'checkpoints'/'ensemble_director_state.json',{}) or {};meta=rj(ROOT/'checkpoints'/'meta_research_director_state.json',{}) or {};feature=rj(ROOT/'checkpoints'/'feature_research_director_state.json',{}) or {};prob=rj(ROOT/'checkpoints'/'probability_director_state.json',{}) or {};exp=rj(ROOT/'checkpoints'/'experiment_director_state.json',{}) or {};hyp=rj(ROOT/'checkpoints'/'hypothesis_generator_state.json',{}) or {};plan=rj(reports/'TEMPORAL_SPLIT_plan.json',{}) or {}
 ledger=rc(reports/'EXPERIMENT_ledger.csv');sid=str(exp.get('split_id') or '');current_ledger=[x for x in ledger if not sid or str(x.get('split_id',''))==sid];promotes=sum(1 for x in current_ledger if x.get('status')=='PROMOTE');last=current_ledger[-1] if current_ledger else {}
 logs=[]
 for p in [ROOT/'logs'/'temporal_sample_optimizer.log',ROOT/'logs'/'universal_model_director.log',ROOT/'logs'/'research_director.log',ROOT/'logs'/'probability_director.log',ROOT/'logs'/'meta_research_director.log',ROOT/'logs'/'feature_research_director.log',ROOT/'logs'/'experiment_director.log',ROOT/'logs'/'hypothesis_generator.log',ROOT/'logs'/'domain_research_director.log',ROOT/'logs'/'ensemble_director.log',ROOT/'logs'/'autonomy_supervisor.log',ROOT/'logs'/'lab_updater.log']:
  for line in tail(p,14):logs.append({'source':p.name,'line':line})
 return {'updated':datetime.now().astimezone().isoformat(),'current':current,'missions':missions,'progress':{'complete':complete,'total':len(missions),'pct':round(complete/len(missions)*100,1) if missions else 0},'supervisor':sup,'temporal':plan,'workers':{'Temporal Optimizer':temporal,'Universal Model':universal,'Probability':prob,'Meta Improve':meta,'Feature Research':feature,'Continuous Experiments':exp,'Hypothesis Generator':hyp,'Domain JRA/NAR':domain,'Ensemble':ensemble},'experiments':{'split_id':sid,'completed':exp.get('completed',len(current_ledger)),'total':exp.get('total',0),'remaining':exp.get('remaining',0),'promotions':promotes,'mode':exp.get('mode','NORMAL'),'threads':exp.get('threads','-'),'last_seconds':exp.get('last_seconds','-'),'last':last},'production':sup.get('production',{}),'quality':sup.get('data_quality',{}),'drift':sup.get('drift',{}),'logs':logs[-160:]}
HTML='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>THE JOCKEY</title><style>:root{--p:#111a24;--l:#263747;--t:#edf4fa;--m:#91a5b5;--g:#59d98e;--w:#f2c85b;--r:#ff7070}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#070b10,#101923);color:var(--t);font-family:Segoe UI,"Yu Gothic UI",sans-serif}header{padding:16px 22px;border-bottom:1px solid var(--l);display:flex;justify-content:space-between;position:sticky;top:0;background:#091018ee}main{max-width:1560px;margin:auto;padding:16px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px}.c{background:var(--p);border:1px solid var(--l);border-radius:14px;padding:15px}.s12{grid-column:span 12}.s8{grid-column:span 8}.s6{grid-column:span 6}.s4{grid-column:span 4}.big{font-size:27px;font-weight:700}.muted{color:var(--m);font-size:12px}.metric{display:flex;justify-content:space-between;border-bottom:1px dashed #263747;padding:7px 0;gap:14px}.g{color:var(--g)}.w{color:var(--w)}.r{color:var(--r)}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #263747;text-align:left;font-size:13px}.log{height:300px;overflow:auto;background:#070c11;padding:10px;border-radius:10px;font:12px Consolas,monospace}@media(max-width:850px){.s8,.s6,.s4{grid-column:span 12}}</style></head><body><header><b>THE JOCKEY｜完全自律研究所</b><span id="updated" class="muted"></span></header><main><div class="grid"><section class="c s8"><div class="muted">CURRENT MISSION</div><div id="mission" class="big"></div><div id="progress" class="muted"></div></section><section class="c s4"><div class="muted">AUTONOMY STATUS</div><div id="auto" class="big"></div></section><section class="c s4"><b>Mother Population</b><div id="population"></div></section><section class="c s4"><b>Temporal Plan</b><div id="temporal"></div></section><section class="c s4"><b>Research Momentum</b><div id="experiments"></div></section><section class="c s4"><b>Turbo Engine</b><div id="turbo"></div></section><section class="c s4"><b>Production Gate</b><div id="production"></div></section><section class="c s4"><b>Last Experiment</b><div id="lastExp"></div></section><section class="c s12"><b>Optimized Time Splits</b><table><thead><tr><th>Split</th><th>期間</th><th>Races</th><th>Rows</th><th>JRA R</th><th>NAR R</th><th>Prior 3+</th></tr></thead><tbody id="splits"></tbody></table></section><section class="c s12"><b>AI Workers</b><div id="workers"></div></section><section class="c s12"><b>Mission DAG</b><table><thead><tr><th>Mission</th><th>状態</th><th>内容</th></tr></thead><tbody id="missions"></tbody></table></section><section class="c s12"><b>Latest Autonomous Logs</b><div id="logs" class="log"></div></section></div></main><script>const m=(k,v,c='')=>`<div class="metric"><span>${k}</span><b class="${c}">${v??'-'}</b></div>`;const cls=s=>['PASS','READY','RUNNING','COMPLETE','RESTARTED','PROMOTE','TURBO'].includes(String(s).toUpperCase())?'g':(['WAITING','WARN','HOLD','PENDING','ALERT','KEEP'].includes(String(s).toUpperCase())?'w':'r');const pct=x=>x===undefined||x===null?'-':(Number(x)*100).toFixed(1)+'%';async function go(){try{let s=await (await fetch('/api/state',{cache:'no-store'})).json();updated.textContent=new Date(s.updated).toLocaleString('ja-JP');mission.textContent=s.current?s.current.id:'QUEUE COMPLETE';progress.textContent=`${s.progress.complete}/${s.progress.total} COMPLETE (${s.progress.pct}%)`;let as=s.supervisor?.status||'WAITING';auto.textContent=as;auto.className='big '+cls(as);let tp=s.temporal||{},p=tp.population||{},dr=tp.date_range||{};population.innerHTML=m('Rows',p.rows?.toLocaleString?.()||p.rows||'-')+m('Races',p.races?.toLocaleString?.()||p.races||'-','g')+m('Horses',p.horses?.toLocaleString?.()||p.horses||'-')+m('JRA Races',p.jra_races||'-')+m('NAR Races',p.nar_races||'-');temporal.innerHTML=m('Status',tp.status||'WAITING',cls(tp.status))+m('Range',dr.start&&dr.end?`${dr.start} → ${dr.end}`:'-')+m('Span',dr.span_days?`${dr.span_days} days`:'-')+m('Warnings',(tp.gates?.warnings||[]).length,'w')+m('Blockers',(tp.gates?.blockers||[]).length,(tp.gates?.blockers||[]).length?'r':'g');let e=s.experiments||{};experiments.innerHTML=m('Experiments',`${e.completed||0} / ${e.total||0}`,'g')+m('Remaining',e.remaining??'-')+m('Promotions',e.promotions||0,'g')+m('Split ID',e.split_id||'-');turbo.innerHTML=m('Mode',e.mode||'-',cls(e.mode))+m('CPU Threads',e.threads||'-','g')+m('Last Experiment',`${e.last_seconds||'-'} sec`)+m('Normal Wait','0 sec','g');production.innerHTML=m('Prediction Model',s.production?.status,cls(s.production?.status))+m('Temporal',s.production?.temporal_status||'-',cls(s.production?.temporal_status))+m('Auto Betting','DISABLED','w');workers.innerHTML=Object.entries(s.workers||{}).map(([k,v])=>m(k,v.status||'WAITING',cls(v.status))).join('');let le=e.last||{};lastExp.innerHTML=m('Result',le.status||'-',cls(le.status))+m('Selection LL',le.selection_logloss||le.select_2024_logloss||'-')+m('Test LL',le.test_logloss||le.test_2025_logloss||'-')+m('OOS LL',le.oos_logloss_report_only||le.oos_2026_logloss_report_only||'-');let ss=tp.splits||{};splits.innerHTML=['TRAIN','VALIDATION','SELECTION','TEST','OOS'].map(n=>{let x=ss[n]||{},d=x.domains||{},h=x.history||{};return `<tr><td><b>${n}</b></td><td>${x.start_date||'-'} → ${x.end_date||'-'}</td><td>${x.races??'-'}</td><td>${x.rows??'-'}</td><td>${d.JRA?.races??'-'}</td><td>${d.NAR?.races??'-'}</td><td>${pct(h.prior_3plus_rate)}</td></tr>`}).join('');missions.innerHTML=(s.missions||[]).map(x=>`<tr><td>${x.id||'-'}</td><td class="${cls(x.state)}">${x.state||'-'}</td><td>${x.name||''}</td></tr>`).join('');logs.innerHTML=(s.logs||[]).map(x=>`<div><span style="color:#607487">[${x.source}]</span> ${String(x.line).replaceAll('&','&amp;').replaceAll('<','&lt;')}</div>`).join('')}catch(e){auto.textContent='ERROR';auto.className='big r'}}go();setInterval(go,3000)</script></body></html>'''
class H(BaseHTTPRequestHandler):
 def sendx(self,status,ct,b):self.send_response(status);self.send_header('Content-Type',ct);self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  p=urlparse(self.path).path
  if p=='/api/state':self.sendx(200,'application/json; charset=utf-8',json.dumps(build(),ensure_ascii=False).encode())
  elif p in ('/','/index.html'):self.sendx(200,'text/html; charset=utf-8',HTML.encode())
  elif p=='/health':self.sendx(200,'text/plain; charset=utf-8',b'ok')
  else:self.sendx(404,'text/plain',b'not found')
 def log_message(self,*a):return
def op():time.sleep(.7);webbrowser.open(f'http://{HOST}:{PORT}')
if __name__=='__main__':
 print('='*68);print(' THE JOCKEY TEMPORAL-OPTIMIZED TURBO Dashboard');print('='*68);print(f'Research root : {ROOT}');print(f'Dashboard     : http://{HOST}:{PORT}');threading.Thread(target=op,daemon=True).start();ThreadingHTTPServer((HOST,PORT),H).serve_forever()
